//! `docs.retrieve@1`: search the records one device holds. The holder filters by the caller's ce-cap grant
//! BEFORE it ranks, so a record the grant does not reach is never scored, never serialised and never leaves the
//! device. Each answer reports, for every collection, how many records matched before and after that filter.
//! Types only: depend on this crate to call the cell; the browser client is generated by ce-wire-gen (ts-web).

ce_wire::api! {
    api DocsRetrieve = "docs.retrieve", version 1;
    types {
        /// Health contract: these three fields, in this order, in every cell.
        pub struct Health { pub ok: bool, pub version: String, pub uptime_s: u64 }
        /// `q` in plain words (1..=200 bytes); at most `k` hits (0 = 10, max 50).
        pub struct SearchReq { pub q: String, pub k: u32 }
        /// One visible record. `scope`: the audience it was published for ("public" or "engineer").
        /// `collection`: which collection on this holder it lives in (factory.docs, twin.records, demo.pages).
        pub struct Hit { pub id: String, pub collection: String, pub kind: String, pub scope: String, pub title: String, pub snippet: String, pub score: f32 }
        /// Per collection, as counted by this holder: `matched` records matched the query before the cap filter,
        /// `visible` of them are in the caller's grant, `hidden` = matched - visible (counts only, never content).
        pub struct CollectionCount { pub collection: String, pub matched: u32, pub visible: u32, pub hidden: u32 }
        /// `device`: device class (never a host name); `cell`: the answering cell and version; `ranker`: how the
        /// visible records were ranked; `scopes`: the scopes the caller's grant reaches here; `took_ms`: inside the cell.
        pub struct SearchResp { pub device: String, pub cell: String, pub ranker: String, pub scopes: Vec<String>, pub counts: Vec<CollectionCount>, pub hits: Vec<Hit>, pub took_ms: f64 }
        /// What this holder holds, by collection and scope (counts only).
        pub struct InfoResp { pub device: String, pub cell: String, pub records: u32, pub counts: Vec<CollectionCount> }
        pub enum SearchError { Invalid(String), Limited(String), Failed(String) }
    }
    ops {
        1 => HealthOp(()) -> Health, needs "docs.retrieve:health";
        2 => Search(SearchReq) -> Result<SearchResp, SearchError>, needs "docs.retrieve:search", deadline_ms 3000;
        3 => Info(()) -> InfoResp, needs "docs.retrieve:search";
    }
}

/// The ability a caller's grant must hold to see records of `scope` (public needs only `docs.retrieve:search`).
pub fn scope_ability(scope: &str) -> String {
    format!("docs.retrieve:scope:{scope}")
}
